# already in the first person before this pass; reworded so the accept line isn't the speech again
STORY['mg_the_well_runs_over'] = ("Every night the great moonwell runs over by a finger's width, and every morning it's settled again. I've been writing down the times, and they match something on the lake. I can't watch both at once. I want someone at the end of Nighthaven's pier to watch the island in the middle of the lake while I watch the well. When the well rises, I'll know, and I think you'll know too, so come back and tell me what you saw.", "Don't take your eyes off the island, even when it seems like nothing is happening.")
STORY['mg_the_same_dream'] = ("I keep a book for my guests to write in, and for the last month half of them have written down the same dream. It's a door under water, and a stair going down. These are people who've never met, writing the same thing in their own words, and it's all in the back half of the book. I want Dr. Sandvik to see it, because she's the only one in the glade who collects dreams on purpose. Take it round the lake to her for me.", "Don't read it on the road, please. They wrote in it for me, not for strangers.")
